import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as a,C as o,c as i,o as s,j as t,G as r,a0 as n,a as l}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Sobre a Academia de Pétanque","description":"","frontmatter":{},"headers":[],"relativePath":"pt/about.md","filePath":"pt/about.md"}');const c=a({name:"pt/about.md"},[["render",function(a,d,c,m,u,p){const h=o("AdBanner"),g=o("AdInArticle");return s(),i("div",null,[d[0]||(d[0]=t("h1",{id:"sobre-a-academia-de-petanque",tabindex:"-1"},[l("Sobre a Academia de Pétanque "),t("a",{class:"header-anchor",href:"#sobre-a-academia-de-petanque","aria-label":'Permalink to "Sobre a Academia de Pétanque"'},"​")],-1)),r(h),d[1]||(d[1]=n('<h2 id="uma-paixao-pela-petanca" tabindex="-1">Uma Paixão pela Petanca <a class="header-anchor" href="#uma-paixao-pela-petanca" aria-label="Permalink to &quot;Uma Paixão pela Petanca&quot;">​</a></h2><p>Bem-vindo à Academia de Pétanque, onde uma profunda paixão pela pétanque tem sido a força motriz por mais de 45 anos. Minha jornada neste esporte tem sido marcada por dedicação, habilidade e entusiasmo constante.</p><p>A petanca não é apenas um jogo; é uma forma de se conectar, criar estratégias e desfrutar do ar livre, e eu tive a sorte de vivenciar suas muitas facetas por quase meio século. Seja o posicionamento preciso de uma bola ou a camaradagem no campo, meu compromisso com a petanca permanece tão forte como sempre.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p>Compartilhar essa paixão com os amigos é o que realmente torna a petanca tão especial. As incontáveis horas passadas no campo, repletas de risos, competição amigável e histórias compartilhadas, criam laços que duram a vida toda.</p><hr><h2 id="minha-missao" tabindex="-1">Minha Missão <a class="header-anchor" href="#minha-missao" aria-label="Permalink to &quot;Minha Missão&quot;">​</a></h2><p>A missão da Academia de Pétanque é ajudar jogadores de elite a desbloquearem todo o seu potencial, abordando o jogo mental – o aspecto muitas vezes negligenciado que diferencia os bons jogadores dos excelentes.</p><p>Por meio deste site, compartilho:</p><ul><li><strong>Estruturas de jogos mentais</strong> desenvolvidas a partir de décadas de experiência</li><li><strong>Ferramentas e modelos práticos</strong> para definição de metas e treinamento</li><li><strong>Metodologias de workshop</strong> para a construção de segurança psicológica</li><li><strong>Abordagens baseadas em evidências</strong> para o desempenho sob pressão</li></ul><p>Não se trata de treinamento técnico, mas sim de criar a base mental que permitirá que suas habilidades técnicas brilhem quando mais importa.</p><hr><h2 id="por-que-eu-criei-este-site" tabindex="-1">Por que eu criei este site <a class="header-anchor" href="#por-que-eu-criei-este-site" aria-label="Permalink to &quot;Por que eu criei este site&quot;">​</a></h2><p>Após mais de 45 anos praticando petanca, vi inúmeros jogadores talentosos lutarem não com a técnica, mas com:</p><ul><li><strong>Crítico interno</strong> que destrói a confiança após erros</li><li><strong>Pressão</strong> que os faz jogar de forma diferente na competição</li><li><strong>Falta de estrutura</strong> no treinamento mental</li><li><strong>Isolamento</strong> em sua jornada de desenvolvimento</li></ul><p>Este site existe para mudar isso. Todo o conteúdo aqui foi desenvolvido para ser imediatamente prático: modelos que você pode copiar, estruturas que você pode aplicar hoje mesmo e ferramentas que funcionam em competições reais.</p><hr>',17)),r(g),d[2]||(d[2]=n('<h2 id="entre-em-contato" tabindex="-1">Entre em contato <a class="header-anchor" href="#entre-em-contato" aria-label="Permalink to &quot;Entre em contato&quot;">​</a></h2><p>Adoraria ouvir de você! Seja para tirar dúvidas, compartilhar sua experiência ou se interessar por workshops e treinamentos, fique à vontade para entrar em contato.</p><h3 id="informacoes-de-contato" tabindex="-1">Informações de contato <a class="header-anchor" href="#informacoes-de-contato" aria-label="Permalink to &quot;Informações de contato&quot;">​</a></h3><p><strong>E-mail:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="ajude-me-a-melhorar-este-site" tabindex="-1">Ajude-me a melhorar este site <a class="header-anchor" href="#ajude-me-a-melhorar-este-site" aria-label="Permalink to &quot;Ajude-me a melhorar este site&quot;">​</a></h2><p>Seu feedback é muito importante! Este site está em constante evolução, baseado nas reais necessidades dos jogadores de elite.</p><p>Adoraria ouvir sua opinião sobre:</p><div class="tip custom-block"><p class="custom-block-title">O que mais lhe ajudaria?</p><ul><li><p><strong>Que tipo de conteúdo você gostaria de ver mais?</strong></p><ul><li>Mais técnicas de jogo mental?</li><li>Mais modelos práticos?</li><li>Estudos de caso de jogadores de elite?</li></ul></li><li><p><strong>O que está faltando no site?</strong></p><ul><li>Há algum tópico não abordado?</li><li>Ferramentas que você gostaria que existissem?</li><li>Recursos que você não consegue encontrar?</li></ul></li><li><p><strong>O que está funcionando bem?</strong></p><ul><li>Quais páginas foram mais úteis?</li><li>Quais ferramentas você realmente utilizou?</li><li>O que fez a maior diferença para você?</li></ul></li><li><p><strong>Como posso melhorar isso?</strong></p><ul><li>Melhorias na navegação?</li><li>Organização de conteúdo? — Mais exemplos?</li><li>Formatos diferentes?</li></ul></li></ul></div><h3 id="envie-me-seu-feedback" tabindex="-1">Envie-me seu feedback <a class="header-anchor" href="#envie-me-seu-feedback" aria-label="Permalink to &quot;Envie-me seu feedback&quot;">​</a></h3><p><strong>Envie suas ideias para:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Sugestões para o assunto do e-mail:</strong></p><ul><li>&quot;Feedback do site: [Seu tópico]&quot;</li><li>&quot;Solicitação de conteúdo: [O que você precisa]&quot;</li><li>&quot;História de Sucesso: [Como Isso Ajudou]&quot;</li><li>&quot;Sugestão: [Sua ideia]&quot;</li></ul><p><strong>O que incluir:</strong></p><ul><li>Seu nível/experiência atual</li><li>Em que você está trabalhando</li><li>Feedback ou solicitações específicas</li><li>Algum caso de sucesso utilizando o conteúdo?</li></ul><hr><h2 id="o-que-outros-estao-dizendo" tabindex="-1">O que outros estão dizendo <a class="header-anchor" href="#o-que-outros-estao-dizendo" aria-label="Permalink to &quot;O que outros estão dizendo&quot;">​</a></h2><details class="details custom-block"><summary>Feedback de jogadores de elite</summary><p><em>&quot;O conteúdo sobre o aspecto mental do jogo mudou completamente a minha forma de encarar as competições. Só o método Inner Coach já valeu a pena ter encontrado este site.&quot;</em> — Campeão Regional, França</p><p><em>&quot;Finalmente, alguém que entende que a técnica não é o problema. A metodologia do workshop deu ao nosso clube uma maneira totalmente nova de treinar.&quot;</em> — Jogador da Seleção Nacional da Suécia</p><p><em>&quot;O modelo de metas e o modelo de diário são exatamente o que eu precisava. Simples, práticos e realmente utilizáveis.&quot;</em> — Jogador de torneio, Espanha</p></details><hr><h2 id="sobre-o-conteudo" tabindex="-1">Sobre o Conteúdo <a class="header-anchor" href="#sobre-o-conteudo" aria-label="Permalink to &quot;Sobre o Conteúdo&quot;">​</a></h2><p>Todo o conteúdo deste site é:</p><ul><li><strong>Gratuito e acessível</strong> - Sem paywalls, sem conteúdo oculto</li><li><strong>Prático e aplicável</strong> - Modelos que você pode usar hoje mesmo</li><li><strong>Baseado em evidências</strong> - Fundamentado em pesquisas de psicologia e mais de 45 anos de experiência</li><li><strong>Atualizado continuamente</strong> - Novo conteúdo adicionado com base no seu feedback</li></ul><hr><h2 id="privacidade-e-cookies" tabindex="-1">Privacidade e Cookies <a class="header-anchor" href="#privacidade-e-cookies" aria-label="Permalink to &quot;Privacidade e Cookies&quot;">​</a></h2><p>Este site utiliza o Google AdSense para ajudar a manter seu funcionamento. Ao usar este site, você concorda com o uso de cookies pelo Google para personalização de anúncios e análise de dados.</p><p><strong>Respeitamos a sua privacidade:</strong></p><ul><li>Não são coletados dados pessoais além dos dados analíticos padrão.</li><li>Sem listas de e-mail ou spam As informações de contato são usadas apenas para responder às suas mensagens.</li></ul><hr><h2 id="conecte-se-e-compartilhe" tabindex="-1">Conecte-se e compartilhe <a class="header-anchor" href="#conecte-se-e-compartilhe" aria-label="Permalink to &quot;Conecte-se e compartilhe&quot;">​</a></h2><p>Se você achar este conteúdo útil:</p><ul><li><strong>Compartilhe</strong> com seus parceiros de treino.</li><li><strong>Recomende</strong> ao seu clube</li><li><strong>Inclua um link para isso</strong> a partir de seus próprios recursos.</li><li><strong>Forneça feedback</strong> para ajudar a melhorar.</li></ul><p>Juntos, podemos elevar o nível do jogo mental da petanca em todo o mundo.</p><hr>',34)),r(h),d[3]||(d[3]=t("p",null,[t("strong",null,"Obrigado por fazer parte da Academia de Pétanque!")],-1)),d[4]||(d[4]=t("p",null,"— Patrik Wiik",-1))])}]]);export{d as __pageData,c as default};
